// The fixed kid roster, generated by tools/generate_kids.py. Same kids every run.
import data from '../../data/kids.json' with { type: 'json' };

export const KIDS = data.kids;
export const KIDS_META = data.meta;
export const KID_BY_ID = new Map(KIDS.map((k) => [k.id, k]));

export function kidName(kid) {
  return kid.nickname ? `${kid.first_name} "${kid.nickname}" ${kid.last_name}` : `${kid.first_name} ${kid.last_name}`;
}

export function shortName(kid) {
  return `${kid.first_name} ${kid.last_name[0]}.`;
}
